def binary_search(nums, target):
    """标准二分，返回下标或 -1。"""
    l, r = 0, len(nums) - 1          # 左闭右闭
    while l <= r:
        mid = l + (r - l) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            l = mid + 1
        else:
            r = mid - 1
    return -1


def lower_bound(nums, target):
    """返回第一个 >= target 的下标（可能等于 len）。"""
    l, r = 0, len(nums)              # 左闭右开
    while l < r:
        mid = l + (r - l) // 2
        if nums[mid] < target:
            l = mid + 1
        else:
            r = mid
    return l

def build_next(p: str):
    """next[i] = p[0..i] 的最长相等前后缀长度（不含自身）。"""
    nxt = [0] * len(p)
    j = 0
    for i in range(1, len(p)):
        while j > 0 and p[i] != p[j]:
            j = nxt[j - 1]
        if p[i] == p[j]:
            j += 1
        nxt[i] = j
    return nxt


def kmp_search(s: str, p: str):
    """返回 p 在 s 中所有出现的起始下标，O(n+m)。"""
    if not p:
        return []
    nxt, j, res = build_next(p), 0, []
    for i, ch in enumerate(s):
        while j > 0 and ch != p[j]:
            j = nxt[j - 1]
        if ch == p[j]:
            j += 1
        if j == len(p):
            res.append(i - len(p) + 1)
            j = nxt[j - 1]
    return res

class DSU:
    """路径压缩 + 按秩（大小）合并，近似 O(alpha(n))。"""
    def __init__(self, n):
        self.p = list(range(n))
        self.rank = [0] * n
        self.count = n                      # 连通分量个数

    def find(self, x):
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]    # 路径减半
            x = self.p[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        self.count -= 1
        return True


def num_islands(grid):
    """岛屿数量（lc200）用并查集实现：把每个 '1' 与左/上邻居 union。"""
    if not grid or not grid[0]:
        return 0
    R, C = len(grid), len(grid[0])
    dsu = DSU(R * C)
    ones = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] != "1":
                continue
            ones += 1
            for dr, dc in ((0, -1), (-1, 0)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == "1":
                    dsu.union(r * C + c, nr * C + nc)
    # 连通分量数 = 并查集中仍以 '1' 为根的集合数
    roots = {dsu.find(r * C + c) for r in range(R) for c in range(C) if grid[r][c] == "1"}
    return len(roots)

import torch

def softmax_stable(x, dim=-1):
    """减去 max 防止 exp 上溢；再用 sum 归一化防止下溢导致除零。"""
    x = x - x.max(dim=dim, keepdim=True).values
    e = torch.exp(x)
    return e / (e.sum(dim=dim, keepdim=True) + 1e-12)


def log_softmax_stable(x, dim=-1):
    """log-sum-exp 技巧：log softmax = x - m - log(sum(exp(x - m)))"""
    m = x.max(dim=dim, keepdim=True).values
    z = x - m
    return z - torch.log(torch.exp(z).sum(dim=dim, keepdim=True))

import torch
import torch.nn.functional as F

def cross_entropy_manual(logits, targets, reduction="mean"):
    """logits:[N,C] targets:[N]（类别索引）。CE = -log softmax(logits)[target]"""
    log_probs = F.log_softmax(logits, dim=-1)
    loss = -log_probs.gather(1, targets.unsqueeze(1)).squeeze(1)
    if reduction == "mean":
        return loss.mean()
    if reduction == "sum":
        return loss.sum()
    return loss


def binary_cross_entropy_manual(logits, targets):
    """多标签分类用：每个类别独立 sigmoid；等价于 softmax+CE 在多标签场景不适用。"""
    return F.binary_cross_entropy_with_logits(logits, targets.float())

